// Golden values reproduced from the prototype's own logic (design lines 3096–5239 run in node:vm, renderValsEN, default
// state: src/features/eco/eco.golden.json, generated by scripts/proto-golden-eco.ts). The domain reads the ECOs as Vigie
// reports them: here the prototype ECOS materialised by the Vigie mirror's seed snapshot (prototypeEcoSnapshot) — the
// same records the database mirror holds. Progress recorded in Keystone (pending sync with Vigie) is asserted on top.
import { describe, expect, it } from 'vitest';
import PROTO from '@/server/prototype/prototype-data.json';
import GEN from '@/server/prototype/prototype-generated.json';
import { prototypeEcoSnapshot, type ProtoEcoRow } from '@/server/integrations/vigie/prototype-snapshot';
import type { VigieEcoRecord } from '@/server/integrations/vigie/types';
import GOLD from '@/features/eco/eco.golden.json';
import {
  approvalDots, approvalsHint, canActOnKey, canDecideDisposition, canSetInterchangeability, costDeltaText, costText, dispositionView, ecoApprovalItems,
  ecoBadge, ecoChips, ecoFilterOf, ecoKpis, ecoRowAction, ecoStatusTag, ecoSteps, effectiveDecision, interchangeabilityView, isOpenEco, keyStates, nextStepOf,
  partsSummary, pendingDispositionsTag, pendingLine, pinnedListText, releasesBlockedText, schedDeltaText, schedText, syncLabelOf, syncStateOf,
  type EcoLike, type EcoProgressLike,
} from './eco';
import { renderTxt } from './home';

/* eslint-disable @typescript-eslint/no-explicit-any */
const P = PROTO as any;
const G = (GOLD as any).en;
const ROLES = ['director', 'pm', 'depthead', 'member', 'englead', 'quality', 'procurement', 'client'] as const;
const TITLES: Record<string, string> = Object.fromEntries(Object.entries(P.PERSONAS as Record<string, [string, string]>).map(([r, [, title]]) => [r, title]));
/** Projects each persona manages (projects.pm): R. Aubert → HLT-026. */
const MANAGED: Record<string, string[]> = { pm: ['HLT-026'] };

const records: VigieEcoRecord[] = prototypeEcoSnapshot({
  ecos: P.ECOS as ProtoEcoRow[],
  projects: ((GEN as any).initialProjects as { code: string; status: string; pm: string }[]).map(({ code, status, pm }) => ({ code, status, pm })),
  usage: Object.fromEntries((P.PARTS as { ref: string; usage: Record<string, number> }[]).map((p) => [p.ref, p.usage])),
  projectNames: P.PROJ_NAMES,
  fleet: P.FLEET,
  asMaintained: P.AS_MAINT,
  englead: 'Antoine Girard',
  quality: 'Gabriel Comte',
});

const like = (r: VigieEcoRecord, progress: EcoProgressLike[] = []): EcoLike & Pick<VigieEcoRecord, 'effectivity'> => ({
  ...r,
  approvals: r.approvals.map((a) => ({ key: a.key, decision: a.decision, approver: a.approver, pending: progress.filter((p) => p.kind === 'approval' && p.approvalKey === a.key).at(-1) ?? null })),
  requestedStatus: progress.filter((p) => p.kind === 'step').at(-1)?.targetStatus ?? null,
  pendingProgress: progress,
});
const ECOS = records.map((r) => like(r));
const byId = (id: string) => ECOS.find((e) => e.number === id)!;
const awaiting = (role: string) => {
  const key = role === 'englead' || role === 'quality' || role === 'pm' ? role : null;
  return key ? ECOS.filter((e) => e.status === 'in_approval' && e.approvals.find((a) => a.key === key)?.decision === 'pending' && (key !== 'pm' || e.projects.some((c) => (MANAGED[role] ?? []).includes(c)))).length : 0;
};
const id = (s: string) => s;

describe('register (ecoKpis, ecoChips, ecoRows — 4342–4350)', () => {
  it.each(ROLES)('%s: KPI tiles', (role) => {
    const key = role === 'englead' || role === 'quality' || role === 'pm' ? role : null;
    const kpis = ecoKpis(ECOS, { roleKey: key, roleTitle: TITLES[role], awaitingMine: awaiting(role), lang: 'en' });
    expect(kpis.map((k) => ({ label: k.label, value: k.value, sub: renderTxt(k.sub, id), color: k.lo ? 'var(--color-accent-300)' : 'var(--color-text)' }))).toEqual(G.eco.byRole[role].kpis);
  });

  it('status chips (All + ECO_FLOW with counts) and the filter parser', () => {
    expect(ecoChips(ECOS).map((c) => ({ label: c.label, count: String(c.count) }))).toEqual(G.eco.chips);
    expect([ecoFilterOf('in_approval'), ecoFilterOf('In approval'), ecoFilterOf(undefined), ecoFilterOf('x')]).toEqual(['in_approval', null, null, null]);
    for (const [label, g] of Object.entries(G.eco.filters as Record<string, { rows: string[] }>)) {
      expect(ECOS.filter((e) => e.status === ecoChips(ECOS).find((c) => c.label === label)!.value).map((e) => e.number)).toEqual(g.rows);
    }
  });

  it('rows: parts, cost, schedule, approval dots, status tag, pending line, step action', () => {
    expect(ECOS.map((e) => {
      const a = ecoRowAction(e);
      const pend = pendingLine(e);
      return {
        id: e.number, parts: partsSummary(e.parts), cost: costText(e.costEur, 'en'), sched: schedText(e.scheduleDays), tagClass: ecoStatusTag(e.status),
        hasPend: !!pend, lockIcon: pend?.icon === 'lock' ? 'ph ph-lock-simple' : 'ph ph-hourglass',
        canStart: a?.kind === 'step' && a.target === 'impact_analysis', canSubmit: a?.kind === 'step' && a.target === 'in_approval', needInterch: a?.kind === 'need-interchangeability',
        approvals: approvalDots(e).map((d) => ({ label: d.label, dot: d.dot })),
      };
    })).toEqual(G.eco.rows.map((r: any) => ({
      id: r.id, parts: r.parts, cost: r.cost, sched: r.sched, tagClass: r.tagClass, hasPend: r.hasPend, lockIcon: r.lockIcon, canStart: r.canStart, canSubmit: r.canSubmit,
      needInterch: r.needInterch, approvals: r.approvals,
    })));
    // pendText of the rows with a pending line
    for (const r of G.eco.rows.filter((x: any) => x.hasPend)) expect(pendingLine(byId(r.id))!.text).toBe(r.pendText);
    expect(ecoBadge(ECOS)).toBe('1');
    expect(ecoBadge([])).toBe('');
    expect(ECOS.filter((e) => isOpenEco(e.status)).length).toBe(3);
  });
});

describe('drawer (ecoVals 4352–4369)', () => {
  const ids = Object.keys(G.eco.drawers);

  it('step indicator, impact texts, interchangeability, pending tag, pinned list', () => {
    for (const n of ids) {
      const e = byId(n);
      const g = G.eco.drawers[n].pm;
      const st = ecoSteps(e.status);
      expect(st.steps.map((s) => (s.reached && !st.rejected ? 'var(--color-accent)' : 'var(--color-neutral-700)'))).toEqual(g.steps.map((s: any) => s.dot));
      expect(st.steps.map((s) => s.label)).toEqual(g.steps.map((s: any) => s.label));
      expect([costDeltaText(e.costEur, 'en'), schedDeltaText(e.scheduleDays)]).toEqual([g.impact[3].v, g.impact[4].v]);
      expect(g.impact[3].color).toBe(e.costEur > 5000 ? 'var(--color-accent-300)' : 'var(--color-text)');
      const iv = interchangeabilityView(e.interchangeability);
      expect([iv.label, iv.tagClass, iv.hint]).toEqual([g.interchLabel, g.interchTag, g.interchHint]);
      const pt = pendingDispositionsTag(e.pendingDispositions);
      expect([pt.text, pt.tagClass, e.locked]).toEqual([g.pendText, g.pendTag, g.isLocked]);
      expect(pinnedListText(e.effectivity)).toBe(g.pinnedList);
      expect([e.effectivity.some((t) => t.targetType === 'machine' && t.disposition === 'retrofit'), e.effectivity.some((t) => t.targetType === 'machine' && t.disposition === 'pinned')])
        .toEqual([g.hasRetrofit, g.hasPinned]);
    }
  });

  it('effectivity targets: revision text, disposition tag, note, decider', () => {
    for (const n of ids) {
      const e = byId(n);
      const g = G.eco.drawers[n].pm;
      const view = (kind: 'project' | 'machine') => e.effectivity.filter((t) => t.targetType === kind).map((t) => {
        const d = dispositionView(t, e);
        return { revText: d.revText, label: d.label, tagClass: d.tagClass, note: d.note, hasNote: !!d.note, decider: d.decider };
      });
      const pick = (xs: any[]) => xs.map((x) => ({ revText: x.revText, label: x.label, tagClass: x.tagClass, note: x.note, hasNote: x.hasNote, decider: x.decider }));
      expect(view('project')).toEqual(pick(g.dispProjects));
      expect(view('machine')).toEqual(pick(g.dispMachines));
    }
  });

  it.each(['director', 'pm', 'englead', 'quality', 'procurement'])('%s: controls Vigie owns now (canSetInterch, canDecide), approval rows and role hint', (role) => {
    for (const n of ids) {
      const e = byId(n);
      const g = G.eco.drawers[n][role];
      expect(canSetInterchangeability(e.status, role)).toBe(g.canSetInterch);
      expect(g.dispProjects.every((t: any) => t.canDecide === canDecideDisposition(e.status, 'project', role))).toBe(true);
      expect(g.dispMachines.every((t: any) => t.canDecide === canDecideDisposition(e.status, 'machine', role))).toBe(true);
      expect(keyStates(e, { role, managedProjects: MANAGED[role] ?? [] }).map((k) => ({ label: k.label, who: k.who, state: k.state, tagClass: k.tagClass, canAct: k.canAct })))
        .toEqual(g.approvers);
      expect(approvalsHint(e.status, role)).toBe(g.roleHint);
    }
  });
});

describe('progress recorded in Keystone, pending sync with Vigie', () => {
  const approve: EcoProgressLike = { kind: 'approval', approvalKey: 'pm', decision: 'ok', targetStatus: null, syncStatus: 'pending' };
  const start: EcoProgressLike = { kind: 'step', approvalKey: null, decision: null, targetStatus: 'impact_analysis', syncStatus: 'pending' };

  it("the PM's approval shows as the effective decision, closes the key and marks the ECO pending sync", () => {
    const e = like(records.find((r) => r.number === 'ECO-2026-015')!, [approve]);
    const before = byId('ECO-2026-015');
    expect(canActOnKey(before, 'pm', { role: 'pm', managedProjects: ['HLT-026'] })).toBe(true);
    expect(canActOnKey(before, 'pm', { role: 'pm', managedProjects: ['NDC-031'] })).toBe(false); // not a PM of an impacted project
    expect(canActOnKey(before, 'pm', { role: 'director', managedProjects: ['HLT-026'] })).toBe(false); // the director holds no key
    expect(canActOnKey(before, 'englead', { role: 'englead', managedProjects: [] })).toBe(false); // already approved in Vigie
    expect(canActOnKey(e, 'pm', { role: 'pm', managedProjects: ['HLT-026'] })).toBe(false);
    expect(effectiveDecision(e.approvals[2])).toBe('ok');
    expect(approvalDots(e).map((d) => [d.dot, d.pendingSync])).toEqual([['var(--color-accent)', false], ['var(--color-accent)', false], ['var(--color-accent)', true]]);
    expect(keyStates(e, { role: 'pm', managedProjects: ['HLT-026'] })[2]).toMatchObject({ state: 'Approved', tagClass: 'tag tag-neutral', sync: 'pending', canAct: false });
    // Vigie decides the status: still "In approval" here (3 dispositions pending in Vigie).
    expect([e.status, syncStateOf(e), syncLabelOf(e)]).toEqual(['in_approval', 'pending', 'Pending sync with Vigie']);
    expect(syncLabelOf(like(records[1], [{ ...approve, syncStatus: 'failed' }]))).toBe('Sync with Vigie failed');
    // Delivered but not yet reflected by the mirror: "Sent to Vigie" (pending still wins while anything waits).
    const sent = like(records[1], [{ ...approve, syncStatus: 'sent' }]);
    expect([syncStateOf(sent), syncLabelOf(sent), approvalDots(sent)[2].sync]).toEqual(['sent', 'Sent to Vigie', 'sent']);
    expect(syncStateOf(like(records[1], [{ ...approve, syncStatus: 'sent' }, { ...approve, approvalKey: 'quality', syncStatus: 'pending' }]))).toBe('pending');
    expect(approvalDots(byId('ECO-2026-015')).map((d) => d.sync)).toEqual([null, null, null]);
    expect(syncStateOf(byId('ECO-2026-015'))).toBeNull();
  });

  it('a step request waits for Vigie: no second request, the row offers no button', () => {
    const draft = byId('ECO-2026-017');
    expect([nextStepOf(draft), ecoRowAction(draft)?.kind]).toEqual(['impact_analysis', 'step']);
    const e = like(records.find((r) => r.number === 'ECO-2026-017')!, [start]);
    expect([e.status, e.requestedStatus, nextStepOf(e), ecoRowAction(e)]).toEqual(['draft', 'impact_analysis', null, null]);
    // Submitting needs the interchangeability decided in Vigie (ECO-2026-016: not assessed).
    expect([nextStepOf(byId('ECO-2026-016')), ecoRowAction(byId('ECO-2026-016'))]).toEqual([null, { kind: 'need-interchangeability', label: 'Set interchangeability' }]);
    expect(nextStepOf({ ...byId('ECO-2026-016'), interchangeability: 'yes' })).toBe('in_approval');
    expect(ecoRowAction({ ...byId('ECO-2026-016'), interchangeability: 'yes' })).toEqual({ kind: 'step', target: 'in_approval', label: 'Submit for approval', variant: 'primary' });
  });

  it('texts', () => {
    expect([releasesBlockedText(0), releasesBlockedText(1), releasesBlockedText(2)]).toEqual(['No release blocked', '1 release blocked', '2 releases blocked']);
    expect([schedText(-6), schedText(4), schedText(0), schedDeltaText(-6), schedDeltaText(0)]).toEqual(['-6 d', '+4 d', '—', '-6 days', 'None']);
    expect([costText(2400, 'fr'), costText(0, 'en'), costDeltaText(0, 'en')]).toEqual(['+2\u202f400 €', '—', 'None']);
  });
});

describe('My approvals items (apprItems 4724)', () => {
  it("reproduce the PM's ECO item, with the inline decision and the Vigie link", () => {
    const items = ecoApprovalItems(
      [{ number: 'ECO-2026-015', title: byId('ECO-2026-015').title, typeLabel: 'Obsolescence notice', projectNames: ['Harbor Line', 'Clinique Pasteur Lyon'], raisedOn: '2026-09-19', requestedBy: 'Gabriel Comte', key: 'pm' }],
      { keystone: (n) => `/reference/eco?eco=${n}`, vigie: (n) => `http://localhost:3200/modifications-techniques/${n}` },
      () => '19 Sep',
    );
    expect(items).toEqual([{
      kind: 'eco', id: 'ECO-2026-015', title: 'Replace CD-200 smoke detector by CD-210 in all open designs', sub: 'Obsolescence notice · Harbor Line, Clinique Pasteur Lyon',
      who: 'Gabriel Comte', when: '19 Sep', whenIso: '2026-09-19', href: '/reference/eco?eco=ECO-2026-015', decision: { mode: 'eco', number: 'ECO-2026-015', key: 'pm' },
      external: { href: 'http://localhost:3200/modifications-techniques/ECO-2026-015', label: 'Open in Vigie' },
    }]);
  });
});
